-- Riprese dell'outreach (25/09/2026, richiesta del founder).
--
-- Chi finisce il primo flusso di un brand senza mai rispondere viene ripreso
-- dallo STESSO brand: Ripresa 1 dopo 30 giorni dall'ultima email (3 email,
-- giorni 0·4·8, oggetto «ti riscrivo»), Ripresa 2 due mesi dopo (2 email,
-- giorni 68·72 della ripresa, oggetto «ci riprovo un'ultima volta»). Dopo,
-- quel brand non gli scrive più: la funzione qui sotto non iscrive mai due
-- volte alla ripresa, e l'arruolamento dalle liste esclude chi ha già avuto un
-- flusso del brand.
--
-- Perché una funzione a parte e non le liste: `outreach_arruola_liste`
-- esclude per costruzione chi è già stato in un flusso del brand, che è
-- esattamente chi va ripreso. Qui le stesse esclusioni (opt-out, rimbalzi,
-- soppressioni, clienti del gestionale, «no» a questo brand) più una: mai
-- risposto a questo brand, autorisposte a parte.
--
-- Il ritmo: 2 riprese al giorno per casella che spedisce, spalmate su 11 ore,
-- con primo_contatto = false — non consumano i «nuovi al giorno» delle caselle.
-- La casella che spedisce la ripresa è quella che aveva scritto il primo
-- flusso (outreach-dispatch, stickyDaStorico): «ti avevo scritto» lo firma
-- chi aveva scritto.
--
-- Tutto nasce SPENTO: sequenze in pausa, collegamenti con attiva = false. Si
-- accende mettendo la sequenza di ripresa in «active» e attiva = true sul
-- collegamento.

-- 1. Quale ripresa segue quale primo flusso ---------------------------------
create table if not exists public.outreach_riprese (
  sequenza_origine uuid primary key references public.outreach_sequences(id) on delete cascade,
  sequenza_ripresa uuid not null references public.outreach_sequences(id) on delete cascade,
  dopo_giorni integer not null default 30 check (dopo_giorni between 1 and 365),
  attiva boolean not null default false,
  created_at timestamptz not null default now(),
  check (sequenza_origine <> sequenza_ripresa)
);
create index if not exists outreach_riprese_ripresa_idx on public.outreach_riprese (sequenza_ripresa);

alter table public.outreach_riprese enable row level security;
revoke all on public.outreach_riprese from anon;
drop policy if exists outreach_riprese_super on public.outreach_riprese;
create policy outreach_riprese_super on public.outreach_riprese
  for all using (is_super_admin()) with check (is_super_admin());
drop policy if exists blocco_utente_bloccato on public.outreach_riprese;
create policy blocco_utente_bloccato on public.outreach_riprese
  as restrictive for all using (not (select utente_bloccato()));

-- 2. Le 7 sequenze di ripresa, in pausa (testi approvati il 25/09/2026) -----
insert into public.outreach_sequences (id, company_id, brand_id, name, description, status)
select v.id, '00000000-0000-0000-0000-000000000001'::uuid, v.brand_id, v.nome,
       'Ripresa per chi ha finito il primo flusso senza rispondere: 3 email dopo 30 giorni, 2 email due mesi dopo.',
       'paused'
  from (values
  ('a496f8fc-716b-5055-b442-8d902ff83dc9'::uuid, 'caa0ec49-8e59-4db0-a05d-bb25bc50bd98'::uuid, $n$Edilizia in Cloud · Ripresa$n$),
  ('fd9912eb-42d4-5870-9404-66e28a70d161'::uuid, '7d52853f-fa86-4f68-9cd5-25ee444cf132'::uuid, $n$Marketing Edile · Bagni · Ripresa$n$),
  ('0c45c328-9b60-521a-912f-044bce48c6df'::uuid, '7d52853f-fa86-4f68-9cd5-25ee444cf132'::uuid, $n$Marketing Edile · Fotovoltaico · Ripresa$n$),
  ('4334ddb7-fa75-5358-ab6e-bddc25313df5'::uuid, '7d52853f-fa86-4f68-9cd5-25ee444cf132'::uuid, $n$Marketing Edile · Serramenti · Ripresa$n$),
  ('a9a8d0cd-7c9a-5cd6-87b7-b98456623f4d'::uuid, '7d52853f-fa86-4f68-9cd5-25ee444cf132'::uuid, $n$Marketing Edile · Tetti · Ripresa$n$),
  ('fce17572-44fd-5dde-972f-cc91f913d82d'::uuid, '93361c3d-bd62-43c5-bca1-aa9380b97953'::uuid, $n$ThermoDMR · Flusso C · Ripresa$n$),
  ('9a3a477e-5534-5be2-9840-81a4abb9fa18'::uuid, '93361c3d-bd62-43c5-bca1-aa9380b97953'::uuid, $n$ThermoDMR · Flusso S · Ripresa$n$)
  ) as v(id, brand_id, nome)
 where exists (select 1 from public.outreach_brands b where b.id = v.brand_id)
on conflict (id) do nothing;

insert into public.outreach_sequence_steps (id, sequence_id, step_order, channel, delay_days, delay_hours, subject, body, node_type)
select v.id, v.seq, v.ordine, 'email', v.giorni, 0, v.oggetto, v.corpo, 'email'
  from (values
  ('0db824c1-d555-5afc-8131-c69ba807c996'::uuid, 'a496f8fc-716b-5055-b442-8d902ff83dc9'::uuid, 1, 0, $o$ti riscrivo$o$, $c$Buongiorno {{nome}},<br><br>ti avevo scritto diverse settimane fa in merito a Edilizia in Cloud, il gestionale per le imprese edili. Immagino che tra cantieri e telefono non ci sia stato il tempo di rispondere, quindi ti riscrivo e provo a spiegarmi meglio.<br><br>Ti ho scritto perché {{azienda|la tua impresa}} lavora nell'edilizia{{#zona}} {{zona}}{{/zona}}, e il gestionale l'abbiamo fatto proprio per imprese come la tua.<br><br>La prima cosa che si nota è il tempo. Rapportini da ricopiare, ore da sommare, bolle da cercare, telefonate per sapere a che punto è un lavoro: è tempo che nessuno conta, ma c'è. Con il gestionale le squadre segnano ore e materiale dal telefono, in cantiere, e il resto si mette insieme da solo. Si risparmiano circa 10 ore al mese per ogni dipendente.<br><br>Fai due conti. Un'ora di lavoro vera, con contributi e tempi morti, costa intorno ai 34 €: sono 340 € al mese per ogni persona. {In un'impresa con 5 dipendenti sono 50 ore al mese, più di sei giornate di lavoro, circa 1.700 € al mese che oggi se ne vanno in carte e telefonate.|In un'impresa con 4 dipendenti sono 40 ore al mese, cinque giornate di lavoro, circa 1.360 € al mese che oggi se ne vanno in carte e telefonate.|In un'impresa con 8 dipendenti sono 80 ore al mese, dieci giornate di lavoro, circa 2.720 € al mese che oggi se ne vanno in carte e telefonate.|In un'impresa con 12 dipendenti sono 120 ore al mese, quindici giornate di lavoro, circa 4.080 € al mese che oggi se ne vanno in carte e telefonate.}<br><br>Non è teoria. Un'impresa nostra cliente, con 450.000 € di fatturato, tra ore recuperate, costi tagliati e una gestione più ordinata ha risparmiato più di 40.000 € in un anno. Soldi che il titolare si è messo in tasca, senza aprire un cantiere in più.<br><br>So che cambiare programma spaventa, soprattutto per il tempo che porta via. Per questo i dati li carichiamo noi, la squadra la formiamo noi, e hai 31 giorni per provarlo senza pagare. Se non ti convince, i tuoi dati te li porti via in Excel.<br><br>Non ti chiedo di decidere niente adesso. Mi basterebbero 10 minuti al telefono per capire se per {{azienda|la tua impresa}} può avere senso. Se preferisci, rispondimi con due righe e ti mando tutto per scritto.<br><br>Se invece non ti interessa, rispondimi «no» e non ti disturbo più.<br><br>Un saluto<br><br>P.S. E il margine di ogni cantiere lo vedi mentre il lavoro è ancora aperto, quando puoi ancora correggere, non quando il cantiere è finito e i soldi sono già andati.$c$),
  ('37956b89-4de2-5373-8226-5a4e5cf39c39'::uuid, 'a496f8fc-716b-5055-b442-8d902ff83dc9'::uuid, 2, 4, $o$$o$, $c$Buongiorno {{nome}},<br><br>riprendo la mail di qualche giorno fa, perché ti ho parlato di ore e di cantieri, ma non della parte che porta i soldi: le offerte ai clienti.<br><br>Pensa a come nascono oggi da te. Il sopralluogo, poi la sera al computer, il file vecchio da ricopiare, i prezzi da ricontrollare, il PDF da mandare. E poi l'attesa, senza sapere se il cliente l'ha anche solo aperto.<br><br>Con Edilizia in Cloud ci metti circa 3 minuti, partendo dal tuo listino. L'offerta esce bella e chiara, con il tuo marchio, e il cliente la firma online dal telefono. Tu vedi quando la apre, e il sistema ti ricorda di richiamarlo prima che scada.<br><br>Chi lo usa vende di più: in media le vendite crescono del 25%. Il motivo è semplice: la tua offerta arriva prima di quella degli altri, si capisce meglio, e si firma subito, senza stampe e scansioni.<br><br>E c'è un effetto che si vede meno ma pesa di più. Un'offerta ordinata, con ogni voce spiegata, si difende da sola: il cliente capisce cosa paga, e tu smetti di togliere il 5% dal prezzo pur di chiudere il lavoro.<br><br>Quando il cliente firma, il preventivo diventa il cantiere: stessi prezzi, stesse voci, e il margine lo controlli da lì.<br><br>Se vuoi vederlo partendo da un tuo lavoro vero, dimmi quando ti chiamo. Se non ti interessa, basta un «no» e non ti scrivo più.<br><br>Un saluto<br><br>P.S. Se in ufficio c'è qualcuno che prepara le offerte al posto tuo, fagli leggere questa mail: di solito è la prima persona a cui cambia la settimana.$c$),
  ('2cfbf24d-9d53-5006-9171-b4744d0727e0'::uuid, 'a496f8fc-716b-5055-b442-8d902ff83dc9'::uuid, 3, 8, $o$$o$, $c$Buongiorno {{nome}},<br><br>per ora è l'ultima mail che ti mando, poi ti lascio lavorare.<br><br>Ti lascio le ultime tre cose che fa il gestionale, quelle di cui di solito ci si accorge solo quando mancano.<br><br>La prima è la cassa. Vedi i soldi che devono entrare e quelli che devono uscire nei prossimi mesi: le rate dei clienti, i fornitori da pagare, le scadenze. Così un mese stretto lo vedi arrivare con settimane di anticipo, e non quando ti chiama la banca.<br><br>La seconda sono le scadenze che nessuno ricorda finché non è tardi. Il DURC dei subappaltatori, le visite mediche e i corsi dei dipendenti, l'assicurazione e la revisione dei mezzi: il gestionale ti avvisa prima che scadano, non quando arriva il controllo in cantiere.<br><br>La terza è l'assistente AI su WhatsApp e al telefono. Risponde ai clienti quando tu sei in cantiere con le mani occupate, e le richieste finiscono nel gestionale invece di perdersi in una chiamata persa.<br><br>Lo so che un gestionale non si sceglie leggendo una mail. Per questo non ti chiedo di comprare niente: se vuoi, ti faccio vedere tutto in videochiamata, partendo da un tuo cantiere, e poi decidi con calma.<br><br>Se ti interessa, rispondimi «sì» e ti chiamo quando ti fa comodo.<br>Se adesso non è il momento, scrivimi «più avanti» e mi faccio sentire tra qualche mese.<br>Se non fa per te, rispondimi «no» e non ti scrivo più.<br><br>Un saluto$c$),
  ('182e4076-f5bd-54ac-b718-f6369eee7ef1'::uuid, 'a496f8fc-716b-5055-b442-8d902ff83dc9'::uuid, 4, 68, $o$ci riprovo un'ultima volta$o$, $c$Buongiorno {{nome}},<br><br>ti avevo scritto un paio di mesi fa in merito a Edilizia in Cloud, il gestionale per le imprese edili. Non ci siamo mai sentiti, e ci riprovo un'ultima volta, e ti rimetto davanti il ragionamento che secondo me vale più di tutte le funzioni messe insieme.<br><br>Per mettere in tasca di più non devi fatturare di più.<br><br>{Facciamo un esempio. Se la tua impresa fattura 1.000.000 € e a fine anno ti restano 100.000 €, per avere il doppio dell'utile vendendo di più dovresti arrivare a 2.000.000 €: il doppio dei cantieri, delle squadre, dei problemi e delle sere passate a fare conti.<br><br>Oppure puoi tenere lo stesso fatturato e recuperare 50.000 € tra errori, sprechi, ore perse e lavori extra mai fatturati. E smettere di togliere il 5% dal prezzo per chiudere i lavori: sono altri 50.000 €. Stesso fatturato, il doppio dell'utile.|Facciamo un esempio. Se la tua impresa fattura 600.000 € e a fine anno ti restano 60.000 €, per avere il doppio dell'utile vendendo di più dovresti arrivare a 1.200.000 €: il doppio dei cantieri, delle squadre, dei problemi e delle sere passate a fare conti.<br><br>Oppure puoi tenere lo stesso fatturato e recuperare 30.000 € tra errori, sprechi, ore perse e lavori extra mai fatturati. E smettere di togliere il 5% dal prezzo per chiudere i lavori: sono altri 30.000 €. Stesso fatturato, il doppio dell'utile.|Facciamo un esempio. Se la tua impresa fattura 1.500.000 € e a fine anno ti restano 150.000 €, per avere il doppio dell'utile vendendo di più dovresti arrivare a 3.000.000 €: il doppio dei cantieri, delle squadre, dei problemi e delle sere passate a fare conti.<br><br>Oppure puoi tenere lo stesso fatturato e recuperare 75.000 € tra errori, sprechi, ore perse e lavori extra mai fatturati. E smettere di togliere il 5% dal prezzo per chiudere i lavori: sono altri 75.000 €. Stesso fatturato, il doppio dell'utile.|Facciamo un esempio. Se la tua impresa fattura 2.500.000 € e a fine anno ti restano 250.000 €, per avere il doppio dell'utile vendendo di più dovresti arrivare a 5.000.000 €: il doppio dei cantieri, delle squadre, dei problemi e delle sere passate a fare conti.<br><br>Oppure puoi tenere lo stesso fatturato e recuperare 125.000 € tra errori, sprechi, ore perse e lavori extra mai fatturati. E smettere di togliere il 5% dal prezzo per chiudere i lavori: sono altri 125.000 €. Stesso fatturato, il doppio dell'utile.}<br><br>È quello che è successo a Teknofinestre. Messi in ordine costi e prezzi, il titolare si è accorto che anche fatturando di meno gli restava in tasca il doppio.<br><br>Il gestionale serve a questo: vedere dove si perdono i soldi mentre il lavoro è aperto, e fare offerte che non hai bisogno di ribassare.<br><br>Per partire non devi fare quasi niente. Ci sentiamo 10 minuti, ci mandi quello che hai, anche Excel o fogli di carta, e il resto lo carichiamo noi. La squadra la formiamo noi. Hai 31 giorni per provarlo senza pagare, e se non ti convince ti porti via i tuoi dati in Excel.<br><br>Se ti va, rispondimi con un numero e l'orario che ti fa comodo. Se non ti interessa, rispondimi «no» e non ti scrivo più.<br><br>Un saluto<br><br>P.S. Per la telefonata non devi preparare niente: le domande te le faccio io.$c$),
  ('b0ec0d68-5b53-59ca-a694-c774c9994475'::uuid, 'a496f8fc-716b-5055-b442-8d902ff83dc9'::uuid, 5, 72, $o$$o$, $c$Buongiorno {{nome}},<br><br>questa è davvero l'ultima mail che ti mando, poi non ti scrivo più.<br><br>Grazie di avermi letto fin qui, anche senza rispondere: di email così ne arrivano tante, lo capisco benissimo. Se in questi mesi ti ho scritto una volta di troppo, scusami.<br><br>Ti lascio solo il riassunto, nel caso ti serva un giorno: circa 10 ore al mese risparmiate per ogni dipendente, offerte ai clienti in 3 minuti che si firmano online, la cassa e le scadenze sotto controllo, il margine di ogni cantiere mentre è aperto. E 31 giorni per provarlo senza pagare.<br><br>E ricordati il conto dell'ultima volta: per mettere in tasca di più non serve fatturare di più. Serve smettere di perdere soldi per strada.<br><br>Se un giorno ti capita di chiudere un cantiere e scoprire che ti ha reso meno di quanto pensavi, rispondi a questa mail. Resta la mia, e ti rispondo io.<br><br>Buon lavoro, e un saluto$c$),
  ('0611391f-d78e-549a-8569-4ef695149200'::uuid, 'fd9912eb-42d4-5870-9404-66e28a70d161'::uuid, 1, 0, $o$ti riscrivo$o$, $c$Buongiorno {{nome}},<br><br>ti avevo scritto diverse settimane fa in merito alle richieste di clienti per le aziende che rifanno bagni in {{regione}}. Immagino tu sia stato preso dal lavoro, quindi ti riscrivo e provo a spiegarmi meglio.<br><br>Ti ho scritto perché rifai bagni{{#zona}} {{zona}}{{/zona}}, e {{azienda|la tua}} è proprio il tipo di azienda con cui lavoriamo: gente che il lavoro lo sa fare, e che vorrebbe scegliersi i clienti invece di aspettarli.<br><br>In pratica facciamo pubblicità per conto di aziende come la tua, solo nella zona dove lavorano, e passiamo a loro le persone che vogliono rifare il bagno. Sei tu a decidere la zona, il tipo di lavoro e i tempi: le richieste che non rientrano non te le mando.<br><br>{Facciamo due conti, con numeri d'esempio e non promesse. Ammettiamo che con 800 € di pubblicità in un mese arrivino 20 appuntamenti in più, tutti nella tua zona e sul lavoro che vuoi fare. Se ne chiudi 4, con un bagno medio da 12.000 €, sono 48.000 € di vendite in un mese. Vuol dire che ogni appuntamento ti è costato 40 € di pubblicità, e ogni euro speso ne ha portati 60 di lavori firmati. La nostra percentuale la paghi solo su quei 4 lavori.|Facciamo due conti, con numeri d'esempio e non promesse. Ammettiamo che con 600 € di pubblicità in un mese arrivino 15 appuntamenti in più, tutti nella tua zona e sul lavoro che vuoi fare. Se ne chiudi 3, con un bagno medio da 13.000 €, sono 39.000 € di vendite in un mese. Vuol dire che ogni appuntamento ti è costato 40 € di pubblicità, e ogni euro speso ne ha portati 65 di lavori firmati. La nostra percentuale la paghi solo su quei 3 lavori.|Facciamo due conti, con numeri d'esempio e non promesse. Ammettiamo che con 1.000 € di pubblicità in un mese arrivino 25 appuntamenti in più, tutti nella tua zona e sul lavoro che vuoi fare. Se ne chiudi 4, con un bagno medio da 11.000 €, sono 44.000 € di vendite in un mese. Vuol dire che ogni appuntamento ti è costato 40 € di pubblicità, e ogni euro speso ne ha portati 44 di lavori firmati. La nostra percentuale la paghi solo su quei 4 lavori.|Facciamo due conti, con numeri d'esempio e non promesse. Ammettiamo che con 1.200 € di pubblicità in un mese arrivino 24 appuntamenti in più, tutti nella tua zona e sul lavoro che vuoi fare. Se ne chiudi 5, con un bagno medio da 12.500 €, sono 62.500 € di vendite in un mese. Vuol dire che ogni appuntamento ti è costato 50 € di pubblicità, e ogni euro speso ne ha portati più di 52 di lavori firmati. La nostra percentuale la paghi solo su quei 5 lavori.}<br><br>L'alternativa la conosci. Il passaparola va a periodi, e quando si ferma te ne accorgi solo quando il calendario è già vuoto. Nel frattempo i sopralluoghi a vuoto si mangiano le giornate: se ne fai 8 al mese e 5 non firmano, sono 5 mezze giornate buttate, più di due giorni di lavoro al mese.<br><br>La cosa che di solito sorprende è come veniamo pagati. Non c'è un canone mensile e non ti chiedo niente in anticipo. La pubblicità la paghi tu direttamente alle piattaforme, con un account a nome tuo, e noi prendiamo una percentuale solo sui lavori che firmi. Se non firmi, non prendiamo niente.<br><br>Non ti chiedo di decidere niente adesso. Mi basterebbero 10 minuti al telefono per capire se per {{azienda|la tua azienda}} può avere senso, e se non ce l'ha te lo dico io per primo. Se preferisci, rispondimi con due righe e ti mando tutto per scritto.<br><br>Se invece non ti interessa, rispondimi «no» e non ti disturbo più.<br><br>Un saluto<br><br>P.S. Un esempio vero, così capisci di cosa parlo: La Tua Finestra, azienda di serramenti, ha fatto 47.000 € di vendite in 30 giorni con 800 € di pubblicità. Non è la media e non te lo prometto, ma è il tipo di mese per cui lavoriamo.$c$),
  ('eb8242cf-4482-5a91-a8b4-0cd97d007186'::uuid, 'fd9912eb-42d4-5870-9404-66e28a70d161'::uuid, 2, 4, $o$$o$, $c$Buongiorno {{nome}},<br><br>riprendo al volo la mail di qualche giorno fa, perché mi sono accorto di non averti detto una cosa.<br><br>Molti titolari mi rispondono: «ho già provato con un'agenzia, arrivavano solo curiosi». Lo capisco, e spesso è vero. Succede quando chi fa le campagne viene pagato comunque, che i contatti siano buoni o no: a fine mese la fattura arriva uguale ({un'agenzia da 1.500 € al mese ti costa 18.000 € l'anno|un'agenzia da 1.200 € al mese ti costa 14.400 € l'anno|un'agenzia da 2.000 € al mese ti costa 24.000 € l'anno|un'agenzia da 1.800 € al mese ti costa 21.600 € l'anno}, anche nei mesi in cui non firmi niente), e a te restano le serate passate a richiamare gente che voleva solo un prezzo.<br><br>Da noi è il contrario: se ti mandiamo persone che non comprano, non prendiamo niente. Per questo ci conviene mandarti poche richieste buone, piuttosto che tante inutili. E per lo stesso motivo lavoriamo con una sola azienda per zona e per settore: due aziende vicine si farebbero la guerra nella stessa asta, con i loro soldi.<br><br>E non ti leghiamo con un contratto che ti costa anche quando sei fermo. Se ad agosto chiudi per ferie e non firmi niente, a noi non devi niente. Se un mese hai più richieste di quelle che riesci a seguire e vuoi fermarti, ci fermiamo: basta dirlo, e siccome la pubblicità la paghi tu, si ferma anche quella spesa. Con un'agenzia di solito firmi per sei o dodici mesi, e il canone lo paghi lo stesso, che tu lavori o no.<br><br>E se un giorno smetti di lavorare con noi, l'account pubblicitario e i contatti restano tuoi, perché sono a nome tuo dal primo giorno.<br><br>Se ti va di parlarne, dimmi tu quando ti chiamo. Se non ti interessa, basta un «no» e non ti scrivo più.<br><br>Un saluto<br><br>P.S. Chi ha fondato Marketing Edile ha un'azienda di serramenti e bagni, e questo sistema lo usa ogni giorno lì, con i suoi soldi. Non ti proponiamo niente che non facciamo prima noi.$c$),
  ('82ace4c0-8f94-5323-858f-e9585175e2f8'::uuid, 'fd9912eb-42d4-5870-9404-66e28a70d161'::uuid, 3, 8, $o$$o$, $c$Buongiorno {{nome}},<br><br>per ora è l'ultima mail che ti mando, poi ti lascio lavorare.<br><br>Prima di chiudere ti lascio le risposte alle domande che mi fanno tutti, così se un giorno ci sentiamo partiamo già chiariti.<br><br>Quanti contatti arrivano? Non te lo prometto, e diffida di chi lo fa: dipende dal budget e dall'asta pubblicitaria, che non decide nessuno di noi. Quello che ti prometto è che i criteri li scrivi tu, e le richieste che non rientrano non le conto.<br><br>Quanto budget serve? Dipende dal settore e da quanto vale un tuo lavoro medio. Sotto una certa soglia non conviene a nessuno dei due, e se è così te lo dico subito.<br><br>Quanto costa? Nessun canone. Una percentuale su quello che firmi davvero.<br><br>E se voglio fermarmi? Ti fermi quando vuoi: ad agosto per le ferie, o quando hai più lavoro di quello che riesci a seguire. Basta scrivermelo, e se sei fermo non paghi niente.<br><br>Se ti interessa anche solo capirne di più, rispondimi «sì» e ti chiamo quando ti fa comodo.<br>Se adesso non è il momento, scrivimi «più avanti» e mi faccio sentire tra qualche mese.<br>Se non fa per te, rispondimi «no» e non ti scrivo più.<br><br>Un saluto$c$),
  ('0cbe8a32-580e-50dd-96b8-1eeffc999446'::uuid, 'fd9912eb-42d4-5870-9404-66e28a70d161'::uuid, 4, 68, $o$ci riprovo un'ultima volta$o$, $c$Buongiorno {{nome}},<br><br>ti avevo scritto un paio di mesi fa in merito alle richieste di clienti per le aziende che rifanno bagni in {{regione}}. Non ci siamo mai sentiti, e ci riprovo un'ultima volta perché credo che per {{azienda|la tua azienda}} possa valerne la pena.<br><br>Forse il dubbio è capire cosa succede se dici «va bene, parliamone». Te lo racconto, così non devi immaginartelo.<br><br>Ci sentiamo 10 minuti. Ti chiedo dove lavori, quanto vale un tuo lavoro medio e che budget avresti in mente. Se i numeri non tornano te lo dico subito, e ci salutiamo senza far perdere tempo a nessuno dei due. Se tornano, decidi tu che richieste vuoi ricevere, e le campagne le prepariamo noi.<br><br>Da lì le richieste ti arrivano con la campagna da cui vengono, così vedi da subito cosa funziona e dove finisce ogni euro. Tu richiami, fai il sopralluogo e firmi. Noi prendiamo la nostra percentuale solo su quello che firmi.<br><br>E ricordati il conto dell'altra volta, con numeri d'esempio: {800 € di pubblicità, 20 appuntamenti in più, 4 bagni firmati da 12.000 €, 48.000 € di vendite in un mese. La nostra percentuale la paghi solo su quei 4 lavori,|600 € di pubblicità, 15 appuntamenti in più, 3 bagni firmati da 13.000 €, 39.000 € di vendite in un mese. La nostra percentuale la paghi solo su quei 3 lavori,|1.000 € di pubblicità, 25 appuntamenti in più, 4 bagni firmati da 11.000 €, 44.000 € di vendite in un mese. La nostra percentuale la paghi solo su quei 4 lavori,|1.200 € di pubblicità, 24 appuntamenti in più, 5 bagni firmati da 12.500 €, 62.500 € di vendite in un mese. La nostra percentuale la paghi solo su quei 5 lavori,} e se in un mese non firmi niente, a noi non devi niente.<br><br>Nessun canone, nessun anticipo, niente da darci prima di aver firmato un lavoro.<br><br>Se ti va, rispondimi con l'orario che ti fa comodo. Se non ti interessa, rispondimi «no» e non ti scrivo più.<br><br>Un saluto<br><br>P.S. Se nel frattempo hai trovato chi ti porta clienti e sei pieno, meglio così: rispondimi «pieno» e non ti disturbo più.$c$),
  ('0092206a-9c9d-55b0-b4b9-b3b2c5c1009f'::uuid, 'fd9912eb-42d4-5870-9404-66e28a70d161'::uuid, 5, 72, $o$$o$, $c$Buongiorno {{nome}},<br><br>questa è davvero l'ultima mail che ti mando, poi non ti scrivo più.<br><br>Grazie di avermi letto fin qui, anche senza rispondere: di email così ne arrivano tante, lo capisco benissimo. Se in questi mesi ti ho scritto una volta di troppo, scusami.<br><br>Ti lascio solo il riassunto, nel caso ti serva un giorno: campagne fatte solo per il tuo settore e la tua zona, con i criteri che decidi tu, nessun canone, una percentuale solo su quello che firmi.<br><br>Se un giorno ti trovi con il calendario da riempire, o sei stanco di rincorrere chi chiede un prezzo e sparisce, rispondi a questa mail. Resta la mia, e ti rispondo io.<br><br>Buon lavoro, e un saluto$c$),
  ('91652e0c-cf8d-5497-ab5a-e4b96bea8a5d'::uuid, '0c45c328-9b60-521a-912f-044bce48c6df'::uuid, 1, 0, $o$ti riscrivo$o$, $c$Buongiorno {{nome}},<br><br>ti avevo scritto diverse settimane fa in merito alle richieste di clienti per le aziende di fotovoltaico in {{regione}}. Immagino tu sia stato preso dal lavoro, quindi ti riscrivo e provo a spiegarmi meglio.<br><br>Ti ho scritto perché lavori nel fotovoltaico{{#zona}} {{zona}}{{/zona}}, e {{azienda|la tua}} è proprio il tipo di azienda con cui lavoriamo: gente che il lavoro lo sa fare, e che vorrebbe scegliersi i clienti invece di aspettarli.<br><br>In pratica facciamo pubblicità per conto di aziende come la tua, solo nella zona dove lavorano, e passiamo a loro le persone che vogliono mettere il fotovoltaico. Sei tu a decidere la zona, il tipo di lavoro e i tempi: le richieste che non rientrano non te le mando.<br><br>{Facciamo due conti, con numeri d'esempio e non promesse. Ammettiamo che con 800 € di pubblicità in un mese arrivino 20 appuntamenti in più, tutti nella tua zona e sul lavoro che vuoi fare. Se ne chiudi 4, con un impianto medio da 11.000 €, sono 44.000 € di vendite in un mese. Vuol dire che ogni appuntamento ti è costato 40 € di pubblicità, e ogni euro speso ne ha portati 55 di lavori firmati. La nostra percentuale la paghi solo su quei 4 impianti.|Facciamo due conti, con numeri d'esempio e non promesse. Ammettiamo che con 1.000 € di pubblicità in un mese arrivino 20 appuntamenti in più, tutti nella tua zona e sul lavoro che vuoi fare. Se ne chiudi 3, con un impianto medio da 12.000 €, sono 36.000 € di vendite in un mese. Vuol dire che ogni appuntamento ti è costato 50 € di pubblicità, e ogni euro speso ne ha portati 36 di lavori firmati. La nostra percentuale la paghi solo su quei 3 impianti.|Facciamo due conti, con numeri d'esempio e non promesse. Ammettiamo che con 1.200 € di pubblicità in un mese arrivino 30 appuntamenti in più, tutti nella tua zona e sul lavoro che vuoi fare. Se ne chiudi 5, con un impianto medio da 10.500 €, sono 52.500 € di vendite in un mese. Vuol dire che ogni appuntamento ti è costato 40 € di pubblicità, e ogni euro speso ne ha portati più di 43 di lavori firmati. La nostra percentuale la paghi solo su quei 5 impianti.|Facciamo due conti, con numeri d'esempio e non promesse. Ammettiamo che con 600 € di pubblicità in un mese arrivino 15 appuntamenti in più, tutti nella tua zona e sul lavoro che vuoi fare. Se ne chiudi 3, con un impianto medio da 9.000 €, sono 27.000 € di vendite in un mese. Vuol dire che ogni appuntamento ti è costato 40 € di pubblicità, e ogni euro speso ne ha portati 45 di lavori firmati. La nostra percentuale la paghi solo su quei 3 impianti.}<br><br>L'alternativa la conosci. Il passaparola va a periodi, e quando si ferma te ne accorgi solo quando il calendario è già vuoto. Nel frattempo i sopralluoghi a vuoto si mangiano le giornate: se ne fai 8 al mese e 5 non firmano, sono 5 mezze giornate buttate, più di due giorni di lavoro al mese.<br><br>La cosa che di solito sorprende è come veniamo pagati. Non c'è un canone mensile e non ti chiedo niente in anticipo. La pubblicità la paghi tu direttamente alle piattaforme, con un account a nome tuo, e noi prendiamo una percentuale solo sui lavori che firmi. Se non firmi, non prendiamo niente.<br><br>Non ti chiedo di decidere niente adesso. Mi basterebbero 10 minuti al telefono per capire se per {{azienda|la tua azienda}} può avere senso, e se non ce l'ha te lo dico io per primo. Se preferisci, rispondimi con due righe e ti mando tutto per scritto.<br><br>Se invece non ti interessa, rispondimi «no» e non ti disturbo più.<br><br>Un saluto<br><br>P.S. Un esempio vero, così capisci di cosa parlo: Enernova, azienda di fotovoltaico, nel primo mese ha fatto 138.000 € di vendite con 2.700 € di pubblicità. È il nostro caso migliore, non la media, e non te lo prometto: ma è il tipo di mese per cui lavoriamo.$c$),
  ('6e76aefa-bcf1-5002-95eb-751a5277aa48'::uuid, '0c45c328-9b60-521a-912f-044bce48c6df'::uuid, 2, 4, $o$$o$, $c$Buongiorno {{nome}},<br><br>riprendo al volo la mail di qualche giorno fa, perché mi sono accorto di non averti detto una cosa.<br><br>Molti titolari mi rispondono: «ho già provato con un'agenzia, arrivavano solo curiosi». Lo capisco, e spesso è vero. Succede quando chi fa le campagne viene pagato comunque, che i contatti siano buoni o no: a fine mese la fattura arriva uguale ({un'agenzia da 1.500 € al mese ti costa 18.000 € l'anno|un'agenzia da 1.200 € al mese ti costa 14.400 € l'anno|un'agenzia da 2.000 € al mese ti costa 24.000 € l'anno|un'agenzia da 1.800 € al mese ti costa 21.600 € l'anno}, anche nei mesi in cui non firmi niente), e a te restano le serate passate a richiamare gente che voleva solo un prezzo.<br><br>Da noi è il contrario: se ti mandiamo persone che non comprano, non prendiamo niente. Per questo ci conviene mandarti poche richieste buone, piuttosto che tante inutili. E per lo stesso motivo lavoriamo con una sola azienda per zona e per settore: due aziende vicine si farebbero la guerra nella stessa asta, con i loro soldi.<br><br>E non ti leghiamo con un contratto che ti costa anche quando sei fermo. Se ad agosto chiudi per ferie e non firmi niente, a noi non devi niente. Se un mese hai più richieste di quelle che riesci a seguire e vuoi fermarti, ci fermiamo: basta dirlo, e siccome la pubblicità la paghi tu, si ferma anche quella spesa. Con un'agenzia di solito firmi per sei o dodici mesi, e il canone lo paghi lo stesso, che tu lavori o no.<br><br>E se un giorno smetti di lavorare con noi, l'account pubblicitario e i contatti restano tuoi, perché sono a nome tuo dal primo giorno.<br><br>Se ti va di parlarne, dimmi tu quando ti chiamo. Se non ti interessa, basta un «no» e non ti scrivo più.<br><br>Un saluto<br><br>P.S. Chi ha fondato Marketing Edile ha un'azienda di serramenti e bagni, e questo sistema lo usa ogni giorno lì, con i suoi soldi. Non ti proponiamo niente che non facciamo prima noi.$c$),
  ('71da1b96-e1d9-5e7b-8580-a4d3cd6c9fb2'::uuid, '0c45c328-9b60-521a-912f-044bce48c6df'::uuid, 3, 8, $o$$o$, $c$Buongiorno {{nome}},<br><br>per ora è l'ultima mail che ti mando, poi ti lascio lavorare.<br><br>Prima di chiudere ti lascio le risposte alle domande che mi fanno tutti, così se un giorno ci sentiamo partiamo già chiariti.<br><br>Quanti contatti arrivano? Non te lo prometto, e diffida di chi lo fa: dipende dal budget e dall'asta pubblicitaria, che non decide nessuno di noi. Quello che ti prometto è che i criteri li scrivi tu, e le richieste che non rientrano non le conto.<br><br>Quanto budget serve? Dipende dal settore e da quanto vale un tuo lavoro medio. Sotto una certa soglia non conviene a nessuno dei due, e se è così te lo dico subito.<br><br>Quanto costa? Nessun canone. Una percentuale su quello che firmi davvero.<br><br>E se voglio fermarmi? Ti fermi quando vuoi: ad agosto per le ferie, o quando hai più lavoro di quello che riesci a seguire. Basta scrivermelo, e se sei fermo non paghi niente.<br><br>Se ti interessa anche solo capirne di più, rispondimi «sì» e ti chiamo quando ti fa comodo.<br>Se adesso non è il momento, scrivimi «più avanti» e mi faccio sentire tra qualche mese.<br>Se non fa per te, rispondimi «no» e non ti scrivo più.<br><br>Un saluto$c$),
  ('c853fa7e-dd3e-5527-9fcc-741798a62ce3'::uuid, '0c45c328-9b60-521a-912f-044bce48c6df'::uuid, 4, 68, $o$ci riprovo un'ultima volta$o$, $c$Buongiorno {{nome}},<br><br>ti avevo scritto un paio di mesi fa in merito alle richieste di clienti per le aziende di fotovoltaico in {{regione}}. Non ci siamo mai sentiti, e ci riprovo un'ultima volta perché credo che per {{azienda|la tua azienda}} possa valerne la pena.<br><br>Forse il dubbio è capire cosa succede se dici «va bene, parliamone». Te lo racconto, così non devi immaginartelo.<br><br>Ci sentiamo 10 minuti. Ti chiedo dove lavori, quanto vale un tuo lavoro medio e che budget avresti in mente. Se i numeri non tornano te lo dico subito, e ci salutiamo senza far perdere tempo a nessuno dei due. Se tornano, decidi tu che richieste vuoi ricevere, e le campagne le prepariamo noi.<br><br>Da lì le richieste ti arrivano con la campagna da cui vengono, così vedi da subito cosa funziona e dove finisce ogni euro. Tu richiami, fai il sopralluogo e firmi. Noi prendiamo la nostra percentuale solo su quello che firmi.<br><br>E ricordati il conto dell'altra volta, con numeri d'esempio: {800 € di pubblicità, 20 appuntamenti in più, 4 impianti firmati da 11.000 €, 44.000 € di vendite in un mese. La nostra percentuale la paghi solo su quei 4 impianti,|1.000 € di pubblicità, 20 appuntamenti in più, 3 impianti firmati da 12.000 €, 36.000 € di vendite in un mese. La nostra percentuale la paghi solo su quei 3 impianti,|1.200 € di pubblicità, 30 appuntamenti in più, 5 impianti firmati da 10.500 €, 52.500 € di vendite in un mese. La nostra percentuale la paghi solo su quei 5 impianti,|600 € di pubblicità, 15 appuntamenti in più, 3 impianti firmati da 9.000 €, 27.000 € di vendite in un mese. La nostra percentuale la paghi solo su quei 3 impianti,} e se in un mese non firmi niente, a noi non devi niente.<br><br>Nessun canone, nessun anticipo, niente da darci prima di aver firmato un lavoro.<br><br>Se ti va, rispondimi con l'orario che ti fa comodo. Se non ti interessa, rispondimi «no» e non ti scrivo più.<br><br>Un saluto<br><br>P.S. Se nel frattempo hai trovato chi ti porta clienti e sei pieno, meglio così: rispondimi «pieno» e non ti disturbo più.$c$),
  ('bbf85f5b-86a4-5615-92e1-f3c35a286fa9'::uuid, '0c45c328-9b60-521a-912f-044bce48c6df'::uuid, 5, 72, $o$$o$, $c$Buongiorno {{nome}},<br><br>questa è davvero l'ultima mail che ti mando, poi non ti scrivo più.<br><br>Grazie di avermi letto fin qui, anche senza rispondere: di email così ne arrivano tante, lo capisco benissimo. Se in questi mesi ti ho scritto una volta di troppo, scusami.<br><br>Ti lascio solo il riassunto, nel caso ti serva un giorno: campagne fatte solo per il tuo settore e la tua zona, con i criteri che decidi tu, nessun canone, una percentuale solo su quello che firmi.<br><br>Se un giorno ti trovi con il calendario da riempire, o sei stanco di rincorrere chi chiede un prezzo e sparisce, rispondi a questa mail. Resta la mia, e ti rispondo io.<br><br>Buon lavoro, e un saluto$c$),
