select v.origine, v.ripresa
  from (values
  ('88325fe8-a90c-4a85-a00e-90047aff4faf'::uuid, 'a496f8fc-716b-5055-b442-8d902ff83dc9'::uuid),
  ('9e3cb8b0-1d82-40f7-b161-bd650d8d4d73'::uuid, 'a496f8fc-716b-5055-b442-8d902ff83dc9'::uuid),
  ('571af13f-1f66-410e-9dab-95d8ae41c610'::uuid, 'a496f8fc-716b-5055-b442-8d902ff83dc9'::uuid),
  ('1db0074c-d994-4c5a-9664-e97ea59a07c9'::uuid, 'a496f8fc-716b-5055-b442-8d902ff83dc9'::uuid),
  ('3afa7cad-7504-4057-80d3-05dc56555d6d'::uuid, 'fd9912eb-42d4-5870-9404-66e28a70d161'::uuid),
  ('80b0694b-c985-4acd-881a-11d1f8a7a163'::uuid, '0c45c328-9b60-521a-912f-044bce48c6df'::uuid),
  ('53e643d4-202a-4001-9498-5b7d70ea7031'::uuid, '4334ddb7-fa75-5358-ab6e-bddc25313df5'::uuid),
  ('caea4e4e-60a5-4b3c-be16-e0effad7a2b6'::uuid, 'a9a8d0cd-7c9a-5cd6-87b7-b98456623f4d'::uuid),
  ('947ad9fa-9f86-48c4-abdc-9de53504e410'::uuid, 'fce17572-44fd-5dde-972f-cc91f913d82d'::uuid),
  ('586c7b7d-89cb-4fe0-88ab-b09c72990f6f'::uuid, '9a3a477e-5534-5be2-9840-81a4abb9fa18'::uuid)
