on conflict (sequenza_origine) do nothing;

-- 3. L'arruolamento notturno --------------------------------------------------
create or replace function public.outreach_arruola_riprese(p_max integer default 1000)
 returns jsonb
 language plpgsql
 set search_path to 'public'
as $function$
declare
  c_piattaforma constant uuid := '00000000-0000-0000-0000-000000000001';
  v_link      record;
  v_c         record;
  v_step      record;
  v_brand     uuid;
  v_tetto     integer;
  v_oggi      integer;
  v_gap       double precision;
  v_orario    timestamptz;
  v_n         integer := 0;
  v_fatti     integer := 0;
  v_enr       uuid;
  v_iscritti  jsonb := '{}'::jsonb;
begin
  if coalesce(p_max, 0) <= 0 then
    return jsonb_build_object('totale', 0);
  end if;
  -- Meglio saltare un giro che bloccare il dispatcher.
  perform set_config('lock_timeout', '5s', true);

  for v_link in
    select r.sequenza_origine, r.sequenza_ripresa, r.dopo_giorni, s.brand_id
      from outreach_riprese r
      join outreach_sequences s on s.id = r.sequenza_ripresa and s.status = 'active'
      join outreach_sequences o on o.id = r.sequenza_origine and o.brand_id = s.brand_id
      join outreach_brands b on b.id = s.brand_id and b.status = 'active'
     where r.attiva
     order by s.brand_id, r.created_at
  loop
    exit when v_fatti >= p_max;

    -- Tetto del giorno per brand: 2 riprese per casella che spedisce. Più
    -- collegamenti dello stesso brand (i 4 flussi di Edilizia in Cloud) se lo
    -- dividono: si conta quello che è già entrato oggi.
    if v_brand is distinct from v_link.brand_id then
      v_brand := v_link.brand_id;
      v_n := 0;
    end if;
    select 2 * count(*) into v_tetto
      from outreach_sender_accounts a
     where a.brand_id = v_link.brand_id
       and a.status in ('active', 'warming')
       and coalesce(a.connection_status, '') <> 'error';
    select count(*) into v_oggi
      from outreach_enrollments e
      join outreach_sequences s on s.id = e.sequence_id and s.brand_id = v_link.brand_id
     where e.sequence_id in (select distinct r.sequenza_ripresa from outreach_riprese r)
       and (e.enrolled_at at time zone 'Europe/Rome')::date = (now() at time zone 'Europe/Rome')::date;
    continue when v_oggi >= v_tetto;
    v_gap := greatest(120, 39600.0 / greatest(v_tetto, 1));

    select st.step_order, st.subject, st.body into v_step
      from outreach_sequence_steps st
     where st.sequence_id = v_link.sequenza_ripresa and st.channel = 'email'
     order by st.step_order
     limit 1;
    if not found then
      continue;
    end if;

    for v_c in
      select e.contact_id, btrim(c.email) as email
        from outreach_enrollments e
        join marketing_contacts c on c.id = e.contact_id
       where e.sequence_id = v_link.sequenza_origine
         and e.status = 'completed'
         and c.company_id = c_piattaforma
         and c.deleted_at is null
         and btrim(coalesce(c.email, '')) ~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
         and not coalesce(c.optout_email, false)
         and not coalesce(c.unsubscribed, false)
         and not coalesce(c.opt_out, false)
         and (c.ricontatta_dopo is null or c.ricontatta_dopo <= now())
         -- l'ultima email del primo flusso è partita da almeno N giorni
         and (select max(q.sent_at) from outreach_send_queue q
               where q.enrollment_id = e.id and q.status = 'sent')
             <= now() - make_interval(days => v_link.dopo_giorni)
         -- mai in una ripresa di questo brand: la ripresa si fa una volta sola
         and not exists (select 1 from outreach_enrollments e2
                           join outreach_riprese r2 on r2.sequenza_ripresa = e2.sequence_id
                           join outreach_sequences s2 on s2.id = e2.sequence_id
                          where e2.contact_id = e.contact_id and s2.brand_id = v_link.brand_id)
         -- mai risposto a questo brand (le autorisposte non contano)
         and not exists (select 1 from outreach_replies rp
                          where rp.contact_id = e.contact_id
                            and coalesce(rp.intent, '') <> 'auto_reply'
                            and (rp.brand_id = v_link.brand_id or rp.brand_id is null))
         and not exists (select 1 from email_suppressions es
                          where es.company_id = c_piattaforma and es.email_normalized = lower(btrim(c.email)))
         -- chi usa il gestionale non riceve un cold
         and not exists (select 1 from profiles p
                          where p.company_id is not null and lower(btrim(p.email)) = lower(btrim(c.email)))
         -- indirizzo chiuso, o «no» a questo brand (come outreach_arruola_liste)
         and not exists (select 1 from outreach_prospect_contacts pc
                          where pc.contact_id = e.contact_id
                            and (pc.stato in ('unsubscribed', 'bounced')
                                 or (pc.stato = 'negative' and exists (
                                       select 1
                                         from outreach_prospect_companies pcc,
                                              lateral jsonb_array_elements(coalesce(pcc.brand_history, '[]'::jsonb)) h
                                        where pcc.id = pc.prospect_company_id
                                          and h->>'brand_id' = v_link.brand_id::text
                                          and h->>'esito' = 'risposta_negativa'))))
         -- azienda o dominio esclusi
         and not exists (select 1 from outreach_prospect_contacts pc
                           join outreach_prospect_companies pco on pco.id = pc.prospect_company_id
                           join outreach_suppression su
                             on (su.scope = 'company' and su.value = pco.company_key)
                             or (su.scope = 'domain' and pco.email_domain is not null and su.value = lower(pco.email_domain))
                          where pc.contact_id = e.contact_id)
       order by e.updated_at
       limit greatest(0, v_tetto - v_oggi)
    loop
      exit when v_fatti >= p_max or v_oggi >= v_tetto;
      v_orario := now() + make_interval(secs => (v_n + random() * 0.8) * v_gap);

      v_enr := null;
      insert into outreach_enrollments (company_id, sequence_id, contact_id, status, current_step, next_action_at)
      values (c_piattaforma, v_link.sequenza_ripresa, v_c.contact_id, 'active', v_step.step_order, v_orario)
      on conflict (sequence_id, contact_id) do nothing
      returning id into v_enr;
      continue when v_enr is null;

      -- primo_contatto = false: la ripresa non consuma i «nuovi al giorno».
      insert into outreach_send_queue (company_id, enrollment_id, contact_id, brand_id, channel, to_email,
                                       subject, body, status, scheduled_for, primo_contatto)
      values (c_piattaforma, v_enr, v_c.contact_id, v_link.brand_id, 'email', v_c.email,
              coalesce(v_step.subject, ''), coalesce(v_step.body, ''), 'queued', v_orario, false);

      update outreach_prospect_contacts
         set stato = 'in_sequence', brand_corrente = v_link.brand_id, updated_at = now()
       where contact_id = v_c.contact_id and stato in ('new', 'locked', 'cooldown', 'in_sequence');

      v_n := v_n + 1;
      v_fatti := v_fatti + 1;
      v_oggi := v_oggi + 1;
      v_iscritti := jsonb_set(v_iscritti, array[v_link.sequenza_ripresa::text],
                              to_jsonb(coalesce((v_iscritti ->> v_link.sequenza_ripresa::text)::int, 0) + 1));
    end loop;
  end loop;

  return jsonb_build_object('totale', v_fatti, 'iscritti', v_iscritti);
end;
$function$;

revoke all on function public.outreach_arruola_riprese(integer) from public, anon, authenticated;
grant execute on function public.outreach_arruola_riprese(integer) to service_role;

-- 4. Ogni mattina alle 7 (ora italiana d'estate), dopo l'arruolamento dalle liste.
select cron.schedule('outreach-arruola-riprese', '0 5 * * *', $cron$select public.outreach_arruola_riprese(1000);$cron$);
